  'Furniture':   { bg: 'rgba(124,92,219,0.15)', fg: '#4a2fa0', c: '#7c5cdb' },
  'Procurement': { bg: 'rgba(47,125,225,0.15)', fg: '#1b4f94', c: '#2f7de1' },
  'Install':     { bg: 'rgba(46,158,79,0.15)',  fg: '#1c6332', c: '#2e9e4f' },
  'App Setup':   { bg: 'rgba(236,122,28,0.15)', fg: '#8f4308', c: '#ec7a1c' },
  'Software':    { bg: 'rgba(224,69,127,0.15)', fg: '#9a1f4f', c: '#e0457f' },
