function fmtLong(s) { var x = pd(s); return DOWS[x.getDay()] + ' ' + MON[x.getMonth()] + ' ' + x.getDate(); }
function shortAddr(a) { return a.replace(/^\d+\s*/, '').replace(/,.*$/, '').replace(/\s+(W|E|N|S)$/, ''); }

var UNITS = host.data.units;

var TASKS = host.data.tasks;

