    act('add_unit', { address: f.address, type: f.type, owner: f.owner, assignee: f.assignee }).then(function (res) { if (res && res.unit_id) comp.setState({ expanded: res.unit_id }); });
    var id = 'u' + Date.now();
    var u = { id: id, address: f.address.trim(), type: f.type, owner: f.owner.trim() || '—', assignee: f.assignee, days: 0, isNew: true, flagCount: 0, stages: ['todo','todo','todo','todo','todo','todo','todo'] };
    this.setState({ units: this.state.units.concat([u]), showAdd: false, form: { address: '', type: 'Apartment', owner: '', assignee: (host.data.team[0] || '') }, expanded: id, view: 'pipeline' });
